    /** The visually prominent variant of the button. */
    variant?: 'default' | 'destructive' | 'outline' | 'secondary' | 'ghost' | 'link';
    /** The size of the button. */
    size?: 'default' | 'sm' | 'lg' | 'icon';
    /** Whether to show a loading state on the button. */
